 async function openCustomerAccount(c:any){setAccount(c);setRemoteAccountLedger(null);setPeriod("all");setFromDate("");setToDate("");setActiveSection("account");const phone=String(c?.phone||"").trim();if(!phone)return;setBusy(true);setMessage("Loading complete company-wide customer history…");try{const {data,error}=await db.rpc("etihad_customer_lookup",{p_org_id:orgId,p_customer_phone:phone});if(error)throw error;if(data?.found){setRemoteAccountLedger(data);setMessage("Customer history loaded across all branches.");}else{setRemoteAccountLedger(null);setMessage("No saved customer or invoice history was found for this phone number.");}}catch(error:any){setMessage("Could not load company-wide customer history: "+(error?.message||"Please refresh and try again."));}finally{setBusy(false);}}
 const list=customers.filter(c=>(c.name+" "+c.phone).toLowerCase().includes(search.toLowerCase())).map(c=>{const inv=customerSales(c);const paid=customerPayments(c).reduce((a,p)=>a+(p.type==="sales_return_refund"?-num(p.amount):num(p.amount)),0);const grossOutstanding=inv.reduce((a,s)=>a+num(s.balance),0);const grossAdvance=credits.filter(x=>x.key===c.key||x.customerPhone===c.phone).reduce((a,x)=>a+num(x.balance??0),0);const outstanding=Math.max(0,grossOutstanding-grossAdvance);const advance=Math.max(0,grossAdvance-grossOutstanding);return {...c,invoices:inv.length,sales:inv.reduce((a,s)=>a+num(s.total),0),outstanding,paid,advance,loyaltyPoints:Math.max(0,inv.reduce((sum,s)=>{const original=Math.max(0,num(s.loyaltyEligibleTotal)||num(s.total));const ratio=original>0?Math.min(1,Math.max(0,num(s.total)/original)):1;return sum+Math.floor(num(s.loyaltyPointsEarned)*ratio)-Math.floor(num(s.loyaltyPointsRedeemed)*ratio);},0)),limit:limits.find(x=>x.key===c.key)?.limit??0};});
