 const events=[...accountSales.map(s=>({kind:"sale",date:s.date||s.createdAt,ref:s.invoiceNo||s.id,data:s})),...accountPayments.map(p=>({kind:"payment",date:p.date||p.createdAt,ref:p.receiptNo||p.invoiceNo||p.id,data:p})),...accountCredits.map(x=>({kind:"advance",date:x.date||x.createdAt,ref:x.id||x.key,data:x}))].sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 async function saveLoyaltySettings(){if(!Number.isFinite(num(earnAmount))||num(earnAmount)<=0||!Number.isFinite(num(earnPoints))||num(earnPoints)<0||!Number.isFinite(num(redeemPoints))||num(redeemPoints)<=0||!Number.isFinite(num(redeemValue))||num(redeemValue)<=0){setMessage("Enter valid positive earning and redemption ratios.");return;}setBusy(true);const data={enabled:loyaltyEnabled,earnAmount:num(earnAmount),earnPoints:num(earnPoints),redeemPoints:num(redeemPoints),redeemValue:num(redeemValue),updatedAt:new Date().toISOString()};const {error}=await db.from("etihad_records").upsert({org_id:orgId,collection:"mberp_loyalty_settings",record_id:"default",branch_ids:[],updated_by:userId,data},{onConflict:"org_id,collection,record_id"});setMessage(error?"Loyalty settings not saved: "+error.message:"Loyalty earning and redemption settings saved.");setBusy(false);if(!error)onSaved();}
